-- 1) New official sources (deep URLs; collision-checked against sources.url first)
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3127, 'https://www.becas.unam.mx/2026/08/10/becas-para-estudios-de-posgrado-en-la-unam-convocatoria-2027-1/', $$Becas para Estudios de Posgrado en la UNAM - Convocatoria 2027-1 (Programa de Becas Elisa Acuña) | Portal de Becas UNAM (official)$$, 'becas.unam.mx', 'scholarship', now(), true, true, now()), (3128, 'https://tec.mx/es/becas-y-creditos-educativos-para-alumnos-internacionales', $$Becas y Créditos Educativos para alumnos internacionales | Tecnológico de Monterrey (official)$$, 'tec.mx', 'scholarship', now(), true, true, now()) RETURNING id, url;

-- 2) Retire 343 (generic importer umbrella; real channels are 707 and 933)
UPDATE scholarships SET title = $$UNAM - 'International Postgraduate Scholarship' is a generic importer label, not a UNAM award; see records 707 and 933 (retired)$$, provider = $$Universidad Nacional Autonoma de Mexico$$, country = $$Mexico$$, coverage_type = $$Unspecified$$, amount_usd_value = 0, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL, deadline = $$Retired - no UNAM award of this name exists and no application round applies. UNAM postgraduate funding runs through the Elisa Acuña CGEP stipend (record 707) and, for foreigners, the AMEXCID government scholarships (record 933).$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[]$$, recurrence = $$none$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Master's", "PhD"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["RETIRED - generic importer label; use record 707 (UNAM Elisa Acuña postgraduate stipend) and record 933 (AMEXCID Mexican Government Excellence Scholarships for Foreigners)"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$RETIRED in Pass 120 (2026-10-28) as a generic duplicate. "UNAM International Postgraduate Scholarship" is an importer umbrella label, not an award UNAM publishes: the stored URL was the Posgrado portal root, and UNAM's actual postgraduate funding landscape is already covered in this catalogue by two verified records. (1) The university's own postgraduate stipend - the Becas para Estudios de Posgrado under the federal Programa de Becas "Elisa Acuña", run by UNAM's Coordinación General de Estudios de Posgrado (CGEP) - is record 707: a monthly living stipend of 4.5 UMA (master's) / 6.0 UMA (doctorate) for newly admitted full-time on-site students, applied for per semester in SIAAPosgrado (fetched 2027-1 call: registration 10-14 August 2026; certified CURP among the documents, so foreign applicants must confirm eligibility with CGEP/their programme). (2) The channel built for foreign nationals is the Mexican Government Excellence Scholarships for Foreigners (AMEXCID), record 933 at reliability 10, which places foreign students at Mexican institutions including UNAM. A third, umbrella row adds nothing but confusion - and its earlier importer incarnation carried an invented USD 15,000 figure and an invented annual June-15 deadline (both removed in 2026). This row is therefore retired; use records 707 and 933.$$ , requirements = $$Do not apply on the basis of this record - it is retired and names no real award. For UNAM postgraduate study, use the two verified channels: the Elisa Acuña CGEP stipend for newly admitted full-time on-site master/doctoral students (record 707; per-semester SIAAPosgrado calls; certified CURP and Mexican bank account among the requirements - confirm foreign eligibility with CGEP), and the AMEXCID Mexican Government Excellence Scholarships for Foreigners (record 933), the federal channel designed for foreign nationals.$$ , website_url = $$https://www.posgrado.unam.mx/$$, source_url = $$https://www.posgrado.unam.mx/$$, application_url = $$https://www.posgrado.unam.mx/$$, funding_type = $$RETIRED - generic importer label duplicating record 707 (UNAM Elisa Acuña postgraduate stipend) and record 933 (AMEXCID foreigners' scholarships)$$, tuition_coverage = $$RETIRED - no coverage of its own; see records 707 and 933.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$Not applicable - retired record.$$ , required_documents = $$[]$$, application_status = $$closed$$, verification_status = $$verified$$, source_reliability = 9, is_active = false, university_id = 91, notes = $$PASS 120 RETIREMENT 2026-10-28 (Mexico cluster): generic importer duplicate. UNAM's fetched postgraduate-scholarship call (becas.unam.mx 2027-1, new source 3127) confirms the university scheme is the Elisa Acuña CGEP stipend already carried as record 707 (uplifted to rel 10 in this same pass), and the foreigner-facing federal channel is AMEXCID (record 933, rel 10). No distinct 'UNAM International Postgraduate Scholarship' exists on the fetched official pages; the stored URL was the Posgrado portal root. Prior history: invented USD 15,000 + annual June-15 deadline removed 2026-10-26, leaving an honest non-verified placeholder. us 471 deleted; root source 2656 retained and (343, 3127) added for audit.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 343 RETURNING id, is_active;

-- 3) Retire 402 (corrupted-name duplicate of 679; stored English URL 404s)
UPDATE scholarships SET title = $$Tecnológico de Monterrey - 'International Scholarship Moss' was a corrupted duplicate of record 679 (retired)$$, provider = $$Tecnologico de Monterrey$$, country = $$Mexico$$, coverage_type = $$Unspecified$$, amount_usd_value = 0, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL, deadline = $$Retired - duplicate record. Tecnológico de Monterrey's scholarships for international students are covered by record 679; this row's stored English URL (tec.mx/en/scholarships) now returns the site's not-found page.$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[]$$, recurrence = $$none$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Bachelor's", "Master's"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["RETIRED - duplicate of record 679 (Tecnológico de Monterrey Scholarships for International Students)"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$RETIRED in Pass 120 (2026-10-28) as a corrupted duplicate. The title "Monterrey International Scholarship Moss" carries an importer artifact ("Moss" is no part of any Tec de Monterrey award name), the stored URL tec.mx/en/scholarships now returns the university's not-found page, and everything real behind it - the Tec's bursaries and educational credits for international undergraduate students (Beca Socioeconómica LATAM, Beca al Talento Académico LATAM, Beca Líderes del Mañana LATAM, the talent bursaries and external loans on the official international-students page) - is already covered by record 679, re-verified first-hand and uplifted to reliability 10 in this same pass. An earlier importer incarnation of this row carried an invented USD 18,000 figure and an invented annual June-28 deadline (removed in 2026). Use record 679.$$ , requirements = $$Do not apply on the basis of this record - it is retired as a duplicate. See record 679 (Tecnológico de Monterrey Scholarships for International Students) for the fetched, current terms: note in particular that the three headline awards are LATAM-scoped, while the talent bursaries on the same official page carry no nationality gate.$$ , website_url = $$https://tec.mx/es/becas-y-creditos-educativos-para-alumnos-internacionales$$, source_url = $$https://tec.mx/es/becas-y-creditos-educativos-para-alumnos-internacionales$$, application_url = $$https://tec.mx/es/becas-y-creditos-educativos-para-alumnos-internacionales$$, funding_type = $$RETIRED - corrupted duplicate of record 679$$, tuition_coverage = $$RETIRED - see record 679.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$Not applicable - retired record.$$ , required_documents = $$[]$$, application_status = $$closed$$, verification_status = $$verified$$, source_reliability = 9, is_active = false, university_id = 226, notes = $$PASS 120 RETIREMENT 2026-10-28 (Mexico cluster): duplicate of record 679 with a corrupted importer title ('...Moss'); stored English URL tec.mx/en/scholarships fetched today returns 'Página no encontrada' (404). The live official page is the Spanish international-students bursaries page (new source 3128), fetched in this pass to uplift the surviving record 679 to rel 10. university_id set to 226 (Tec catalogue row) for correct attribution. Root source 2626 retained for audit.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 402 RETURNING id, is_active;

-- 4) Uplift 679 rel 7 -> 10 (honest LATAM scope; fetched Spanish page)
UPDATE scholarships SET title = $$Tecnológico de Monterrey Scholarships for International Students$$, provider = $$Technological de Monterrey (Tecnológico de Monterrey)$$, country = $$Mexico$$, coverage_type = $$Partial Tuition$$, amount_usd_value = 0, award_amount = NULL, award_currency = $$MXN$$, award_period = $$year$$, award_basis = $$variable$$, deadline = $$No single deadline exists: each award on the page runs its own annual call (for August undergraduate entry) with its own calendar embedded in the official page - check the current call on the linked page before applying. The page read in October 2026 still embeds the 2022-23 calls' calendars (e.g. Talento Académico LATAM: admissions file complete by early February, call closes late February, results in March; Líderes del Mañana LATAM: registration closes late February, results at the end of May), so treat those as the recurring shape, not as current dates.$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[{"name": "Annual calls for August entry", "status": "each award publishes its own calendar on the official page; the embedded calendars read in Oct 2026 were the 2022-23 editions - verify the current call before applying", "deadline_date": null}]$$, recurrence = $$annual$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Bachelor's"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["Headline awards are Latin-America-scoped - see description; the talent bursaries on the same page carry no nationality gate"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = true, merit_based = true, description = $$Tecnológico de Monterrey's official page "Becas y Créditos Educativos para alumnos internacionales" (fetched 2026-10-25 and again 2026-10-28; the university's English scholarships URL now returns not-found, so the Spanish page linked here is the operative source). WHAT THE PAGE ACTUALLY OFFERS, WITH ITS REAL GEOGRAPHIC SCOPE - read this before assuming eligibility: The three HEADLINE undergraduate awards are restricted to Latin America. (1) Beca Socioeconómica LATAM - need-based percentage-of-tuition award (share set by the family's documented economic situation) for new-entry students from Latin American countries; requires parallel admission via solicitud.tec.mx, admission-test score >= 1,220 (or an officially converted SAT >= 1,320), accumulated school average >= 85/100, a non-refundable MXN 750 bursary-process fee, and on acceptance a tuition advance of MXN 9,000 (MXN 15,000 for capacity-limited programmes such as Business and Medicine); the Comité de Becas decides finally. (2) Beca al Talento Académico LATAM - pure-merit award (independent of economic situation) of 30%, 40%, 50%, 60% or 70% of tuition for candidates who completed (or are finishing) high school in 21 listed countries: Argentina, Chile, Venezuela, El Salvador, Colombia, Bolivia, Honduras, Ecuador, Guatemala, Nicaragua, Perú, Costa Rica, Panamá, República Dominicana, Brasil, Paraguay, Uruguay, Cuba, Trinidad y Tobago, Puerto Rico and Haití; annual call for August entry; requires school average >= 90/100 and admission-test score >= 1,300 (up to two attempts); recipients must keep >= 85/100 each period, pass all subjects and a full study load. (3) Beca Líderes del Mañana LATAM - annual 100%-of-tuition award for new-entry students who finished high school in Guatemala, Belice/Belize, Honduras, El Salvador, Nicaragua, Costa Rica, Panamá or República Dominicana, with average >= 90/100, admission-test >= 1,300, proven need of full support, evidence of a social/community project, and a reciprocity commitment after graduation. SCOPE WARNING FOR READERS OUTSIDE LATIN AMERICA (including Central Asia): none of those three awards is open to you. What the same page lists WITHOUT a nationality gate are the talent bursaries for new-entry undergraduates - Beca al Talento Atlético (annual; per-campus availability; evidence review and tryouts; representative teams), Artístico, de Liderazgo, Emprendedor, Creativo and Transformador - plus educational-credit routes (US Federal Direct/Plus Loans and GI Bill for US-linked students; Inversión Educativa TEC financing). Percent support for talent bursaries is set per call/campus and is not stated as a single figure on this page, so no amount is encoded. Fees quoted: MXN 750 socioeconomic-process fee; tuition advances MXN 9,000 / 15,000.$$ , requirements = $$Eligibility (fetched official page, Spanish; admission itself runs separately at solicitud.tec.mx). This page describes the Tec's undergraduate (pregrado) support for international students; it is a family of distinct schemes, not one award. LATIN-AMERICA-ONLY AWARDS: Socioeconómica LATAM (need-based tuition percentage; Latin American origin; admission test >= 1,220 or converted SAT >= 1,320; school average >= 85/100; MXN 750 non-refundable process fee; MXN 9,000 - or 15,000 for capacity-limited programmes - tuition advance on acceptance); Talento Académico LATAM (30-70% of tuition by merit regardless of income; high school taken in one of the 21 listed Latin American countries; average >= 90/100; admission test >= 1,300; annual call for August entry; keep >= 85/100 and pass everything to retain); Líderes del Mañana LATAM (100% of tuition; high school in Guatemala, Belize, Honduras, El Salvador, Nicaragua, Costa Rica, Panama or the Dominican Republic; average >= 90/100; test >= 1,300; proven full-support need; community-project evidence; reciprocity pledge; no previous university studies). Awards are limited in number; meeting the minima does not guarantee one; committee decisions are final. NO NATIONALITY GATE stated on the page: the talent bursaries (Atlético, Artístico, Liderazgo, Emprendedor, Creativo, Transformador) - new-entry students, annual calls, availability by campus, evidence/portfolio review and tryouts or auditions; beneficiaries must satisfy the Reglamento de Becas (linked requirements PDF) to keep support. Loans/financing on the same page (US federal loans, GI Bill, Inversión Educativa TEC) are credits, not scholarships. Programme delivery is in Spanish (English-taught elements exist at the Tec, but this page states no English-test figure; none is encoded). Each call publishes its own dates on the page - verify the current edition before applying; the calendars visible in October 2026 were the 2022-23 calls.$$ , funding_type = $$Percentage tuition bursaries (30-70% merit / need-based percentage / 100% for the 8-country Líderes scheme) plus talent bursaries and loan routes$$, tuition_coverage = $$Variable by scheme: need-based percentage (Socioeconómica LATAM), 30/40/50/60/70% (Talento Académico LATAM), 100% (Líderes del Mañana LATAM, 8 countries); talent-bursary percentages are set per call. All three headline awards are restricted to Latin American students.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$No IELTS (or other English-test) figure is stated on the fetched Spanish page; Tec undergraduate delivery is predominantly in Spanish, so check language-of-instruction and any test requirements against your specific programme/campus admissions page.$$ , required_documents = $$["Completed Tec admission application (solicitud.tec.mx) - admission runs in parallel with every bursary process", "Official high-school grades proving the required average (>=85/100 socioeconomic; >=90/100 Talento Académico / Líderes)", "Tec academic-aptitude admission test at/above the scheme threshold (>=1,220 socioeconomic, or officially converted SAT >=1,320; >=1,300 Talento Académico / Líderes)", "Socioeconómica/Líderes only: family income and asset evidence for the socioeconomic study; MXN 750 non-refundable process fee (Socioeconómica)", "Líderes del Mañana only: evidence, testimonials and qualitative/quantitative results of a social or community project; reciprocity commitment", "Talent bursaries only: the evidence the call asks for (e.g. sports trajectory PDF plus a max. 3-minute competition video for Atlético) and participation in tryouts/auditions"]$$, application_status = $$upcoming$$, verification_status = $$verified$$, source_reliability = 10, is_active = true, university_id = 226, notes = $$PASS 120 UPLIFT rel 7 -> 10 (2026-10-28): official Spanish international-students bursaries page re-fetched first-hand (chunks covering the menu, Socioeconómica, Talento Académico, Líderes del Mañana and talent sections); stored English URL tec.mx/en/scholarships now 404s. Repairs vs the 2026-10-25 verification: award_basis 'range' normalized to 'variable'; application_status 'unknown' -> 'upcoming' with an annual-call rounds pattern (page embeds 2022-23 calendars - no current fixed date encoded); eligible_countries ["All"] replaced with the honest fetched scope (three LATAM-only headline awards; talent bursaries ungated); Líderes country list corrected to the fetched 8 (Nicaragua was missing); financial_need_based set true alongside merit (two of three headline schemes are need-linked). Source 3128 inserted and linked (this record previously had no source link). Surviving record of the Tec pair: 402 ('...Moss') retired into this row in the same pass. us 197 resynced.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 679 RETURNING id, source_reliability;

-- 5) Uplift 707 rel 8 -> 10 (fetched Convocatoria 2027-1)
UPDATE scholarships SET title = $$UNAM Becas para Estudios de Posgrado (Elisa Acuña) - Postgraduate Student Support$$, provider = $$Universidad Nacional Autonoma de Mexico$$, country = $$Mexico$$, coverage_type = $$Living Stipend$$, amount_usd_value = 0, award_amount = NULL, award_currency = $$MXN$$, award_period = $$month$$, award_basis = $$variable$$, deadline = $$Semester calls (each semester's new-entry cohort). The fetched 2027-1 call registered 10-14 August 2026 via SIAAPosgrado and is closed; watch the Portal de Becas UNAM and Gaceta UNAM for the next semester's call - exact windows are published per semester, so no fixed deadline is encoded.$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[{"name": "Convocatoria 2027-1", "status": "closed - registration ran 10-14 August 2026 in SIAAPosgrado", "deadline_date": null}, {"name": "Per-semester calls", "status": "a call opens for each semester's new entrants; exact window published per semester on the Portal de Becas UNAM / Gaceta UNAM", "deadline_date": null}]$$, recurrence = $$per_semester$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Master's", "PhD"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["New full-time on-site UNAM master/doctoral students in programmes listed in the call's operating rules; the fetched call requires a certified CURP and runs under the federal Elisa Acuña programme - foreign applicants must confirm eligibility with CGEP/their programme"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$UNAM's postgraduate student-support stipend, run by the Secretaría General and the Coordinación General de Estudios de Posgrado (CGEP) under the federal Programa de Becas "Elisa Acuña" (fetched official call: Convocatoria 2027-1, Portal de Becas UNAM, 2026-10-28; programme page posgrado.unam.mx/becas-y-apoyos/becas-unam/). What it is: a monthly living stipend paid by bank transfer in Mexican pesos (MXN) to NEWLY ENTERING master's and doctoral students who study full-time and on-site (presencial) in study plans listed in the programme's operating rules. Monthly rates are fixed in UMA (Unidad de Medida y Actualización): 4.5 UMA for master's and 6.0 UMA for doctorate - the peso amount therefore moves with the annual UMA value, and no peso or dollar figure is encoded. Core conditions in the fetched call: hold no other support for the same purpose from another institution, and have no job income beyond the equivalent of 8 hours/week; registration in SIAAPosgrado ("beca CGEP" section) during the call window (2027-1: 10-14 August 2026, now closed). Foreigner note: the call text states no Mexican-nationality condition, but it does require a certified CURP (constancia de la Clave Única de Registro de Población, certified/verified with Registro Civil - a document foreign residents in Mexico can hold), a current bank statement of an account in the applicant's name, and - only if registered with the tax authority (SAT) - a recent tax-status certificate; and the scheme runs under the federal Elisa Acuña programme whose operating rules are published in the Diario Oficial de la Federación. Prospective foreign applicants should therefore confirm eligibility directly with CGEP/their programme before counting on this stipend; the channel designed for foreign nationals is the AMEXCID Mexican Government Excellence Scholarship (record 933). This record replaces retired umbrella 343 as the catalogue's UNAM postgraduate-support entry.$$ , requirements = $$From the fetched Convocatoria 2027-1 (Portal de Becas UNAM). Who may apply: newly admitted students (alumnas/alumnos de nuevo ingreso) enrolled full-time in on-site master's or doctoral programmes whose study plans are listed in the Lineamientos de Operación of the UNAM postgraduate-scholarship programme (Elisa Acuña framework); applicants must hold no other support for the same purpose and must not receive employment income greater than the equivalent of 8 hours per week, unless expressly authorised. Registration is in SIAAPosgrado (INGRESO AL SISTEMA > beca CGEP) during the published window (2027-1: 10-14 August 2026). Documents to upload: proof of official semester enrolment; certificate of the immediately preceding degree with its grade average (licenciatura for master's applicants, maestría for doctoral applicants); the system personal-data form ("Imprime tu ficha") and the commitment letter acknowledging the operating rules; bank statement no older than 3 months showing account holder, bank and interbank CLABE; certified CURP (verified with Registro Civil, from gob.mx), current year; SAT constancia de situación fiscal only if registered with the tax authority (no older than 1 month); work-centre certificate (post, hours, seniority, pay) where applicable. The call is published in the Gaceta UNAM and on the Portal de Becas each semester. No GPA minimum and no English-test minimum are stated in the fetched call (prior-degree average is evidenced via the certificate), so none are encoded. Queries per the call: apersbec@unam.mx / becaseconomicas@posgrado.unam.mx.$$ , funding_type = $$Monthly postgraduate living stipend - 4.5 UMA (master's) / 6.0 UMA (doctorate) paid in MXN by bank transfer$$, tuition_coverage = $$Not a tuition waiver: the call defines a monthly living stipend only ($MXN bank transfer at 4.5 / 6.0 UMA by level); UNAM's public-university semester charges are separate.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$No English-test requirement is stated in the fetched call; UNAM postgraduate study is in Spanish - check your programme's own admission languages.$$ , required_documents = $$["Proof of official semester enrolment (new-entry master's/doctoral, full-time, on-site programme listed in the operating rules)", "Certificate of the immediately preceding degree showing grade average (licenciatura for master's applicants; maestría for doctoral)", "SIAAPosgrado personal-data form (Imprime tu ficha) and signed commitment letter accepting the operating rules", "Bank statement no older than 3 months (account holder, bank, interbank CLABE)", "Certified CURP (verified with Registro Civil, gob.mx), current year", "SAT tax-status certificate only if registered with the tax authority (no older than 1 month); work-centre certificate where applicable"]$$, website_url = $$https://www.becas.unam.mx/2026/08/10/becas-para-estudios-de-posgrado-en-la-unam-convocatoria-2027-1/$$, source_url = $$https://www.becas.unam.mx/2026/08/10/becas-para-estudios-de-posgrado-en-la-unam-convocatoria-2027-1/$$, application_url = $$https://www.becas.unam.mx/2026/08/10/becas-para-estudios-de-posgrado-en-la-unam-convocatoria-2027-1/$$, application_status = $$upcoming$$, verification_status = $$verified$$, source_reliability = 10, is_active = true, university_id = 91, notes = $$PASS 120 UPLIFT rel 8 -> 10 (2026-10-28): official Convocatoria 2027-1 fetched first-hand from becas.unam.mx (new source 3127, linked - this record previously had no source link). Repairs vs the 2026-10-25 verification: application_status 'closed' -> 'upcoming' (the scheme calls per semester; only the 2027-1 cycle is closed); deadline_type 'range' -> 'not_published' with the closed cycle + per-semester pattern in rounds; award_basis 'fixed' -> 'variable' (two UMA rates by level); SAT tax certificate corrected to conditional ('en caso de estar dado de alta en el SAT'); <=8 hrs/week job-income rule and no-other-support rule now fronted; CURP/federal-programme foreigner caveat kept explicit (fetched call states no nationality bar; DOF operating rules not fetched, so no stronger claim either way). Generic umbrella 343 retired into this record + AMEXCID 933 in the same pass. us 88 resynced.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 707 RETURNING id, source_reliability;

