-- 7) university_scholarships sync (corrected statements; see header note)
UPDATE university_scholarships SET university_id = 226, scholarship_name = $$Tecnológico de Monterrey Scholarships for International Students$$, availability_status = $$available$$, funding_type = $$Partial Tuition (percentage bursaries)$$, eligibility_notes = $$Verified 2026-10-25 and uplifted 2026-10-28 from the official Spanish page Becas y Creditos Educativos para alumnos internacionales (the English URL 404s). Headline awards are Latin-America-only: Beca Socioeconomica LATAM (need-based %; test >=1,220 or converted SAT >=1,320; avg >=85/100; MXN 750 fee; MXN 9,000/15,000 advance); Beca al Talento Academico LATAM (30/40/50/60/70% merit; high school in one of 21 listed LATAM countries; avg >=90/100; test >=1,300; annual for August entry); Beca Lideres del mañana LATAM (100% tuition; Guatemala, Belize, Honduras, El Salvador, Nicaragua, Costa Rica, Panama, Dominican Republic; avg >=90/100; test >=1,300; social-project evidence; reciprocity pledge). Talent bursaries (Atletico, Artistico, Liderazgo, Emprendedor, Creativo, Transformador) on the same page carry no nationality gate; US federal loans / GI Bill / Inversion Educativa TEC are credit routes, not grants. No fixed date is encoded; annual calls publish calendars on the page (2022-23 editions visible Oct 2026).$$ , official_url = $$https://tec.mx/es/becas-y-creditos-educativos-para-alumnos-internacionales$$, verification_status = $$verified$$, last_verified_at = now(), scholarship_id = 679 WHERE id = 197 RETURNING id;

UPDATE university_scholarships SET university_id = 91, scholarship_name = $$UNAM Becas para Estudios de Posgrado (Elisa Acuña) - Postgraduate Student Support$$, availability_status = $$available$$, funding_type = $$Living Stipend$$, eligibility_notes = $$Verified 2026-10-25 and uplifted 2026-10-28 from the official Convocatoria 2027-1 (Portal de Becas UNAM). Monthly living stipend in MXN by bank transfer: 4.5 UMA master's / 6.0 UMA doctorado, for newly entering full-time on-site students in programmes listed in the operating rules; no other support for the same purpose; job income capped at the equivalent of 8 hrs/week. Registration in SIAAPosgrado per semester (2027-1 ran 10-14 Aug 2026). Documents include semester enrolment, prior-degree certificate with average, bank statement <=3 months, certified CURP (verified with Registro Civil) and, only if registered, SAT tax-status certificate. The call states no Mexican-nationality condition, but the scheme runs under the federal Elisa Acuña programme (DOF rules); foreign applicants should confirm eligibility with CGEP/their programme - the foreigner-facing federal channel is AMEXCID (record 933). No fixed deadline encoded.$$ , official_url = $$https://www.becas.unam.mx/2026/08/10/becas-para-estudios-de-posgrado-en-la-unam-convocatoria-2027-1/$$, verification_status = $$verified$$, last_verified_at = now(), scholarship_id = 707 WHERE id = 88 RETURNING id;

